 if(D.isStaff())nav.append(navButton('Indicadores','chart','overview'));if(D.canManageGoals())nav.append(navButton('Gerenciar Metas','target','goals'));if(isRegistryManager())nav.append(navButton('Cadastro','users','registry'));
 nav.append(el('p','nav-group-label performance-label','Performance'),navButton('Desempenho','chart','performance'));if(D.isStaff()||D.performanceStaff())nav.append(navButton('Indicadores','chart','analytics'));
